// AiServiceHandler is an implementation of the tank.ai.v1.AiService service.
type AiServiceHandler interface {
	ListConversations(context.Context, *connect.Request[v1.ListConversationsRequest]) (*connect.Response[v1.ListConversationsResponse], error)
	GetConversation(context.Context, *connect.Request[v1.GetConversationRequest]) (*connect.Response[v1.GetConversationResponse], error)
	CreateConversation(context.Context, *connect.Request[v1.CreateConversationRequest]) (*connect.Response[v1.CreateConversationResponse], error)
	UpdateConversation(context.Context, *connect.Request[v1.UpdateConversationRequest]) (*connect.Response[v1.UpdateConversationResponse], error)
	DeleteConversation(context.Context, *connect.Request[v1.DeleteConversationRequest]) (*connect.Response[v1.DeleteConversationResponse], error)
	SendMessage(context.Context, *connect.Request[v1.SendMessageRequest], *connect.ServerStream[v1.SendMessageResponse]) error
	RateMessage(context.Context, *connect.Request[v1.RateMessageRequest]) (*connect.Response[v1.RateMessageResponse], error)
	StopReply(context.Context, *connect.Request[v1.StopReplyRequest]) (*connect.Response[v1.StopReplyResponse], error)
	GetSettings(context.Context, *connect.Request[v1.GetSettingsRequest]) (*connect.Response[v1.GetSettingsResponse], error)
	UpdateSettings(context.Context, *connect.Request[v1.UpdateSettingsRequest]) (*connect.Response[v1.UpdateSettingsResponse], error)
	GetUsage(context.Context, *connect.Request[v1.GetUsageRequest]) (*connect.Response[v1.GetUsageResponse], error)
	AddToAtlas(context.Context, *connect.Request[v1.AddToAtlasRequest]) (*connect.Response[v1.AddToAtlasResponse], error)
	// Every app published to Neural, for the "Connect apps" picker.
	ListApps(context.Context, *connect.Request[v1.ListAppsRequest]) (*connect.Response[v1.ListAppsResponse], error)
	ConnectApp(context.Context, *connect.Request[v1.ConnectAppRequest]) (*connect.Response[v1.ConnectAppResponse], error)
	DisconnectApp(context.Context, *connect.Request[v1.DisconnectAppRequest]) (*connect.Response[v1.DisconnectAppResponse], error)
	// Signing in to an app that requires it: the address of the app's own sign-in page, which
	// the client opens in the system browser; it comes back to return_to when done.
	StartAppLogin(context.Context, *connect.Request[v1.StartAppLoginRequest]) (*connect.Response[v1.StartAppLoginResponse], error)
	ListAppAccounts(context.Context, *connect.Request[v1.ListAppAccountsRequest]) (*connect.Response[v1.ListAppAccountsResponse], error)
	SignOutOfApp(context.Context, *connect.Request[v1.SignOutOfAppRequest]) (*connect.Response[v1.SignOutOfAppResponse], error)
	// Takes an overlay off the camera.
	ClearOverlay(context.Context, *connect.Request[v1.ClearOverlayRequest]) (*connect.Response[v1.ClearOverlayResponse], error)
	// Reads every overlay's figures again where they are more than ten minutes old, from where
	// the phone is now. Clients call it while the camera is showing.
	RefreshOverlays(context.Context, *connect.Request[v1.RefreshOverlaysRequest]) (*connect.Response[v1.RefreshOverlaysResponse], error)
	// People (docs/neural-people/PLAN.md). An invite is a link shown once when made; opening it
	// signed in joins the conversation.
	CreateInvite(context.Context, *connect.Request[v1.CreateInviteRequest]) (*connect.Response[v1.CreateInviteResponse], error)
	// What a link leads to, for the page that asks whether to join.
	PreviewInvite(context.Context, *connect.Request[v1.PreviewInviteRequest]) (*connect.Response[v1.PreviewInviteResponse], error)
	JoinConversation(context.Context, *connect.Request[v1.JoinConversationRequest]) (*connect.Response[v1.JoinConversationResponse], error)
	LeaveConversation(context.Context, *connect.Request[v1.LeaveConversationRequest]) (*connect.Response[v1.LeaveConversationResponse], error)
	// The owner takes someone out.
	RemoveMember(context.Context, *connect.Request[v1.RemoveMemberRequest]) (*connect.Response[v1.RemoveMemberResponse], error)
	// Everything that happens in a conversation, live, for every member with it open: messages
	// from anyone, Neural's reply as it is written, people, devices and overlays changing.
	Watch(context.Context, *connect.Request[v1.WatchRequest], *connect.ServerStream[v1.WatchResponse]) error
	// The caller is typing; the others see it for a few seconds.
	SetTyping(context.Context, *connect.Request[v1.SetTypingRequest]) (*connect.Response[v1.SetTypingResponse], error)
	// The caller has read the conversation up to now.
	MarkRead(context.Context, *connect.Request[v1.MarkReadRequest]) (*connect.Response[v1.MarkReadResponse], error)
	SetMuted(context.Context, *connect.Request[v1.SetMutedRequest]) (*connect.Response[v1.SetMutedResponse], error)
	// Voice in the composer: a short recording the person made, written out as text by TANK's
	// own hearing model (never another company's, never the device's dictation). The words go
	// back into the composer for the person to edit and send; nothing is sent or kept.
	Transcribe(context.Context, *connect.Request[v1.TranscribeRequest]) (*connect.Response[v1.TranscribeResponse], error)
	// Emoji reactions on any message in a conversation the caller is in. A reaction is quiet: it
	// never asks Neural for a reply and never sends a notification. Everyone watching gets
	// WatchResponse.reactions. Adding one already there, or removing one that is not, is no error.
	AddReaction(context.Context, *connect.Request[v1.AddReactionRequest]) (*connect.Response[v1.AddReactionResponse], error)
	RemoveReaction(context.Context, *connect.Request[v1.RemoveReactionRequest]) (*connect.Response[v1.RemoveReactionResponse], error)
	// The caller's read receipts switch for one conversation (Conversation.read_receipts). Off by
	// default, for every member of every conversation. Turning it on shares only what happens from
	// then on: nothing read while it was off is ever shown as read.
	SetReadReceipts(context.Context, *connect.Request[v1.SetReadReceiptsRequest]) (*connect.Response[v1.SetReadReceiptsResponse], error)
	// The client has received messages (in the chat list, say): the newest it has in each
	// conversation. Reading implies it (MarkRead, and a Watch that delivers a message), so a
	// conversation on screen needs no call. A conversation the caller is not in is skipped.
	MarkDelivered(context.Context, *connect.Request[v1.MarkDeliveredRequest]) (*connect.Response[v1.MarkDeliveredResponse], error)
}

